class ResultIterator(object):
    '''The result of a findall() operation.

    Each element is a Result instance.
    '''
    def __init__(self, parser, string, pos, endpos, evaluate_result=True):
        self.parser = parser
        self.string = string
        self.pos = pos
        self.endpos = endpos
        self.evaluate_result = evaluate_result

    def __iter__(self):
        return self

    def _adjust_pos_for_alignment(self, m):
        """Adjust position for left/center aligned fields to stop at next space."""
        # Check if the format contains left or center alignment
        import re
        # Look for alignment specs in the format: {:<[fill]>}, {:^[fill]>}
        align_pattern = re.compile(r'\{[^}]*:[^}]*[<^]')
        has_align = bool(align_pattern.search(self.parser._format))

        if has_align:
            # Get the matched text and strip trailing fill characters (default is space)
            matched = m.group(0)
            # Find where the actual content ends by stripping trailing spaces
            stripped = matched.rstrip(' ')
            if len(stripped) < len(matched):
                # Calculate the offset within the match where content ends
                offset = len(matched) - len(stripped)
                return m.start() + len(stripped)
        return m.end()

    def __next__(self):
        m = self.parser._search_re.search(self.string, self.pos, self.endpos)
        if m is None:
            raise StopIteration()
        self.pos = self._adjust_pos_for_alignment(m)

        if self.evaluate_result:
            return self.parser.evaluate_result(m)
        else:
            return Match(self.parser, m)

    # pre-py3k compat
    next = __next__

